// The docs pages read the generated manifest through the package's public export, as a consumer
// would. It is generated by `pnpm build` (packages/react's tsdown `build:before` hook), so in
// development an edit to a contract, a `.docs.ts` or a prop's JSDoc shows after `pnpm build`.
import type { Manifest } from '@senakster/senui';
import manifestJson from '@senakster/senui/components.json';

// The package exports only `Manifest`; its parts are reached through it.
export type ManifestComponent = Manifest['components'][string];
export type ManifestProp = ManifestComponent['props'][number];
export type ManifestForbidden = ManifestComponent['forbidden'][number];
export type ManifestStory = ManifestComponent['stories'][number];

export const manifest: Manifest = manifestJson;

export function componentEntry(name: string): ManifestComponent | undefined {
  return manifest.components[name];
}

/** `components-button--default` → `components-button`: the id every entry of that title shares. */
function titleId(storyId: string): string {
  return storyId.slice(0, storyId.indexOf('--'));
}

/** The docs entry id of a component: `components-button--docs`. */
export function docsId(component: ManifestComponent): string | undefined {
  const first = component.stories[0];
  return first ? `${titleId(first.id)}--docs` : undefined;
}

/**
 * Where a link in a published string goes on the docs site. Docs pages render in Storybook's
 * preview frame (`iframe.html`), which sits at the site root, so a path from the package's `dist`
 * root (`USAGE.md`) is also a path from the page. Links to another component's docs and to a story
 * open in the manager (`./?path=…`, in the top window), and stay path-relative so they work under
 * the Pages subpath.
 */
export function siteHref(target: string): { href: string; top?: boolean } {
  if (target.startsWith('?path=')) return { href: `./${target}`, top: true };
  return { href: target };
}

/** A link to another component's docs page, in the published string syntax. */
export function docLink(name: string): string {
  const component = manifest.components[name];
  const id = component && docsId(component);
  return id ? `[${name}](?path=/docs/${id})` : `\`${name}\``;
}

/** A link to one of the component's stories, on this site. */
export function storyLink(story: ManifestStory): string {
  return `?path=/story/${story.id}`;
}
